// Spatial Locality: Preferred Access Order
// C/C++ arrays are row-major (last index is contiguous)
#define N 1024
int M[N][N];

// GOOD: Stride 1 (j varies fast)
for (int i = 0; i < N; i++)
    for (int j = 0; j < N; j++)
        M[i][j]++;

// BAD: Stride N (i varies fast, large cache misses)
for (int j = 0; j < N; j++)
    for (int i = 0; i < N; i++)
        M[i][j]++;

// Temporal Locality: Loop Tiling (Blocking)
// Maximizes reuse of A and B before eviction
#define TILE_SIZE 32

for (int ii = 0; ii < N; ii += TILE_SIZE)
    for (int jj = 0; jj < N; jj += TILE_SIZE)
        for (int kk = 0; kk < N; kk += TILE_SIZE)
            for (int i = ii; i < ii + TILE_SIZE; i++)
                for (int j = jj; j < jj + TILE_SIZE; j++)
                    for (int k = kk; k < kk + TILE_SIZE; k++)
                        C[i][j] += A[i][k] * B[k][j];

// Data Alignment: Preventing False Sharing (C++11/17)
#define CACHE_LINE_SIZE 64

// Variables placed on separate cache lines
struct AlignedVars {
    alignas(CACHE_LINE_SIZE) long counter1; // Accessed by Thread A
    alignas(CACHE_LINE_SIZE) long counter2; // Accessed by Thread B
};

// Data Structure Layout: Array of Structures (AoS) vs. Structure of Arrays (SoA)
// SoA generally improves spatial locality if only a few fields are used
struct PointAoS { float x, y, z; int id; };
PointAoS points_aos[100]; // Bad locality if only accessing 'z'

struct PointsSoA {
    float x[100];
    float y[100];
    float z[100]; // Good spatial locality if only z is used
    int id[100];
};
